(function(root){
'use strict';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function parseProducts(raw){const lines=String(raw||'').split('\n').map(x=>x.trim()).filter(Boolean);if(lines.length>20)throw Error('El catálogo admite hasta 20 productos.');return lines.map((line,index)=>{const [name,price,...extra]=line.split('|').map(x=>x.trim());if(!name||!price||extra.length||!/^\d+(?:[.,]\d{1,2})?$/.test(price))throw Error('Revisa el producto '+(index+1)+': usa nombre | precio, por ejemplo Café | 2.50.');const n=Number(price.replace(',','.'));if(!Number.isFinite(n)||n>1000000)throw Error('El precio del producto '+(index+1)+' no es válido.');return {name:name.slice(0,120),price:n};});}
function generate(data){
const themes={electric:{bg:'#061e3b',accent:'#00c9d8',ink:'#fff',paper:'#fff',text:'#142e46',font:'Arial, sans-serif'},editorial:{bg:'#f1f4f8',accent:'#3d5cbe',ink:'#182c42',paper:'#fff',text:'#182c42',font:'Georgia, serif'},warm:{bg:'#f6eee4',accent:'#a65329',ink:'#392920',paper:'#fffaf5',text:'#392920',font:'Georgia, serif'}};
const t=themes[data.theme]||themes.electric;const business=escape(data.business);const desc=escape(data.description);const phone=String(data.phone||'').replace(/\D/g,'');const email=String(data.email||'');const validEmail=/^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/.test(email);const href=phone?'https://wa.me/'+phone+'?text='+encodeURIComponent('Hola, quisiera información de '+data.business):validEmail?'mailto:'+email:'#contacto';const services=String(data.services||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,8);const products=parseProducts(data.products);const store=data.package==='store';const logo=/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(data.logo||'')?'<img class="logo" src="'+data.logo+'" alt="'+business+'">':'';
const productHtml=products.map((p,index)=>'<article class="item"><span class="number">'+String(index+1).padStart(2,'0')+'</span><h3>'+escape(p.name)+'</h3><strong class="price">$'+p.price.toFixed(2)+'</strong>'+(store?'<button class="button" data-add="'+index+'">Añadir al carrito</button>':phone?'<a class="button" target="_blank" rel="noopener noreferrer" href="https://wa.me/'+phone+'?text='+encodeURIComponent('Hola, me interesa '+p.name+' de '+data.business)+'">Consultar por WhatsApp</a>':'<a class="button" href="#contacto">Consultar producto</a>')+'</article>').join('');
const cartScript=store?'<script>(()=>{const products='+JSON.stringify(products).replace(/</g,'\\u003c')+';const quantities=new Map();const summary=document.getElementById("cart-summary");function render(){summary.replaceChildren();let total=0;for(const [index,q] of quantities){const p=products[index];total+=p.price*q;const line=document.createElement("div");line.className="cart-line";const text=document.createElement("span");text.textContent=q+" × "+p.name+" — $"+(p.price*q).toFixed(2);const remove=document.createElement("button");remove.type="button";remove.textContent="Quitar uno";remove.onclick=()=>{if(q<=1)quantities.delete(index);else quantities.set(index,q-1);render();};line.append(text,remove);summary.append(line);}document.getElementById("cart-total").textContent="$"+total.toFixed(2);document.getElementById("cart-empty").hidden=quantities.size>0;}document.querySelectorAll("[data-add]").forEach(b=>b.onclick=()=>{const i=Number(b.dataset.add);quantities.set(i,Math.min((quantities.get(i)||0)+1,20));render();});document.getElementById("clear").onclick=()=>{quantities.clear();render();};render();})();<\/script>':'';
return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+business+' · Borrador</title><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:'+t.paper+';color:'+t.text+';font:16px/1.6 Arial,sans-serif}a{color:inherit}.demo{padding:9px 22px;background:#ecf4fa;color:#36556d;font-size:12px;text-align:center}.wrap{max-width:1120px;margin:auto;padding:0 30px}header{border-bottom:1px solid #bccad544}.nav{min-height:86px;display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{font-size:23px;font-weight:bold;line-height:1.2;display:flex;gap:14px;align-items:center}.logo{max-height:60px;max-width:130px;object-fit:contain}.nav a{text-decoration:none;font-size:14px}.hero{background:'+t.bg+';color:'+t.ink+';padding:85px 0}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:12px;font-weight:bold;color:'+t.accent+'}.hero h1{font:normal clamp(36px,6vw,68px)/1.1 '+t.font+';letter-spacing:-1.5px;max-width:830px;margin:20px 0}.hero p{max-width:620px;font-size:18px;opacity:.8;margin-bottom:30px}.button{display:inline-block;border:0;border-radius:5px;padding:13px 20px;background:'+t.accent+';color:'+(data.theme==='electric'?'#062448':'white')+';text-decoration:none;font-weight:bold;font-size:14px;cursor:pointer}.section{padding:65px 0}h2{font:normal 36px/1.2 '+t.font+';margin:12px 0 30px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.item{border:1px solid #9eafbe55;padding:26px;border-radius:7px;display:flex;flex-direction:column;align-items:flex-start}.number{color:'+t.accent+';font-size:13px}.item h3{font-size:21px;line-height:1.3;margin:16px 0}.price{font-size:25px;margin-bottom:25px}.item .button{margin-top:auto}.contact{background:'+t.bg+';color:'+t.ink+'}.contact a{overflow-wrap:anywhere}.contact p{max-width:650px}.cart-line{display:flex;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid #9eafbe55}.cart-line button{border:1px solid #9eafbe;padding:6px 10px;background:transparent;color:'+t.text+';cursor:pointer}footer{padding:25px 0;font-size:13px;color:#65798b}.total{font-weight:bold;font-size:23px;margin:22px 0}.fine{font-size:13px;opacity:.75}@media(max-width:650px){.wrap{padding:0 22px}.hero{padding:55px 0}.hero h1{font-size:42px}.hero p{font-size:17px}.grid{grid-template-columns:1fr}.section{padding:45px 0}.nav{min-height:76px}.brand{font-size:20px}.logo{max-width:80px;max-height:48px}h2{font-size:31px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}a:focus-visible,button:focus-visible{outline:3px solid '+t.accent+';outline-offset:4px}</style></head><body><div class="demo">Borrador de Robalino Digital · Pendiente de revisión y publicación'+(store?' · Tienda de demostración sin cobros':'')+'</div><header><div class="wrap nav"><div class="brand">'+logo+business+'</div><a href="#contacto">Contacto</a></div></header><main><section class="hero"><div class="wrap"><div class="eyebrow">'+escape(data.city||'Conoce nuestro negocio')+'</div><h1>'+escape(data.headline||data.business)+'</h1><p>'+desc+'</p><a class="button" href="'+escape(href)+'"'+(phone?' target="_blank" rel="noopener noreferrer"':'')+'>Hablemos</a></div></section>'+(services.length?'<section class="section"><div class="wrap"><div class="eyebrow">Lo que ofrecemos</div><h2>Nuestros servicios</h2><div class="grid">'+services.map((name,index)=>'<article class="item"><span class="number">'+String(index+1).padStart(2,'0')+'</span><h3>'+escape(name)+'</h3></article>').join('')+'</div></div></section>':'')+(products.length?'<section class="section"><div class="wrap"><div class="eyebrow">'+(store?'Nuestra colección':'Catálogo')+'</div><h2>Explora nuestros productos</h2><div class="grid">'+productHtml+'</div></div></section>':'')+(store?'<section class="section"><div class="wrap"><h2>Tu carrito de ejemplo</h2><p id="cart-empty">Todavía no has añadido productos.</p><div id="cart-summary"></div><div class="total">Subtotal: <span id="cart-total">$0.00</span></div><button class="button" id="clear">Vaciar carrito</button><p class="fine">Demostración sin pagos. Entrega, impuestos y pasarela de pago se configuran al contratar la tienda.</p></div></section>':'')+'<section class="section contact" id="contacto"><div class="wrap"><div class="eyebrow">Contacto</div><h2>Conversemos</h2><p>'+desc+'</p>'+(phone?'<p><a target="_blank" rel="noopener noreferrer" href="https://wa.me/'+phone+'">WhatsApp: '+escape(data.phone)+'</a></p>':'')+(validEmail?'<p><a href="mailto:'+escape(email)+'">'+escape(email)+'</a></p>':'')+(!phone&&!validEmail?'<p class="fine">Añade un número de WhatsApp o correo en el generador para completar el contacto.</p>':'')+'</div></section></main><footer><div class="wrap">'+business+' · Borrador creado con Robalino Digital</div></footer>'+cartScript+'</body></html>';
}
root.RDBuilder={generate,parseProducts,escape};if(typeof module!=='undefined'&&module.exports)module.exports=root.RDBuilder;
})(typeof window!=='undefined'?window:globalThis);
